"use client";
import { useEffect, useState, useRef } from "react";
import { getCookie, hasCookie } from "cookies-next";
import { useSearchParams } from "next/navigation";
import Breadcrumb from "@/components/header/breadcrumb";
import { TourModalsProvider } from "@/components/tour-detail-page/tour-modals-context";
import Places from "@/components/tour-detail-page/places";
import Info from "@/components/tour-detail-page/info";
import Overview from "@/components/tour-detail-page/overview";
import Includes from "@/components/tour-detail-page/includes";
import Itineraries from "@/components/tour-detail-page/itineraries";
import GoodToKnow from "@/components/tour-detail-page/good-to-know";
import Highlights from "@/components/tour-detail-page/highlights";
import Route from "@/components/tour-detail-page/route";
import Gallery from "@/components/tour-detail-page/gallery";
import GalleryMobil from "@/components/tour-detail-page/gallery-mobil";
import Lightbox from "yet-another-react-lightbox";
import Slideshow from "yet-another-react-lightbox/plugins/slideshow";
import Thumbnails from "yet-another-react-lightbox/plugins/thumbnails";
import Zoom from "yet-another-react-lightbox/plugins/zoom";
import Counter from "yet-another-react-lightbox/plugins/counter";
import StarIcon from "../../../../public/icons/StarIcon";
import "yet-another-react-lightbox/plugins/thumbnails.css";
import "yet-another-react-lightbox/plugins/counter.css";
import "yet-another-react-lightbox/styles.css";
import getTourDetail from "@/services/tourDetailService";
import { getPaymentDetail } from "@/services/booking/paymentDetail";
import GallerySingle from "@/components/tour-detail-page/gallery-single";
import { primaryBtnCls, outlineBtnCls } from "@/components/tour-detail-page/ui";

export default function BookingTourDetailPage({
  referenceId,
}: {
  referenceId: string;
}) {
  const searchParams = useSearchParams();
  const [tourDetailsLoading, setTourDetailsLoading] = useState(true);
  const [loadError, setLoadError] = useState(false);
  const [isUser, setIsUser] = useState(false);
  const [tourData, setTourData] = useState<any>({});
  const [tourImages, setTourImages] = useState<any>({});
  const isInitialMount = useRef(true);
  const [data, setData] = useState({
    start_date: "",
    subject: "",
    token: "",
    total_amount: 0,
    paid_amount: 0,
    original_amount: 0,
    discount_amount: 0,
    coupon_amount: 0,
    total_discount: 0,
    final_amount: 0,
    remaining_amount: 0,
    tour: {
      id: 0,
      name: "",
      slug: "",
      image: "",
      startsAt: "",
      endsAt: "",
      start_location: "",
      end_location: "",
      pickup_time: "",
      dropoff_time: "",
      suitable_ages: "",
      duration_days: 0,
      languages: [{ id: 0, name: "" }],
      defaults: { accommodation: false },
      guide_type: { name: { en: "" } },
    },
    items: [],
  });

  const fetchDetails = async () => {
    try {
      const res = await getPaymentDetail(
        referenceId,
        searchParams.get("token")!,
      );
      setData({
        ...data,
        start_date: res.data.start_date,
        subject: res.data.subject,
        token: res.data.token,
        total_amount: parseFloat(res.data.total_amount),
        paid_amount: parseFloat(res.data.paid_amount),
        original_amount: parseFloat(res.data.original_amount),
        discount_amount: parseFloat(res.data.discount_amount),
        coupon_amount: parseFloat(res.data.coupon_amount),
        total_discount: parseFloat(res.data.total_discount),
        final_amount: parseFloat(res.data.final_amount),
        remaining_amount: parseFloat(res.data.remaining_amount),
        tour: {
          ...data.tour,
          id: res.data.tour.id,
          name: res.data.tour.name,
          slug: res.data.tour.slug,
          image: res.data.tour.image,
          start_location: res.data.tour.start_location,
          end_location: res.data.tour.end_location,
          pickup_time: res.data.tour.pickup_time,
          dropoff_time: res.data.tour.dropoff_time,
          suitable_ages: res.data.tour.suitable_ages,
          duration_days: res.data.tour.duration_days,
          languages: res.data.tour.languages,
          defaults: res.data.tour.defaults,
          guide_type: res.data.tour.guide_type,
        },
        items: res.data.items,
      });

      await fetchTourDetails(res.data.tour.slug);
      setTourDetailsLoading(false);
    } catch (error) {
      setLoadError(true);
      setTourDetailsLoading(false);
    }
  };

  const fetchTourDetails = async (slug: string) => {
    const res = await getTourDetail(slug);
    setTourData(res);
    setTourImages(
      res.media.map((item: any) => {
        var url = "";

        if (item.high) url = item.high;
        else if (item.main) url = item.main;
        else return null;

        return {
          imageUrl: url,
        };
      }),
    );
  };

  useEffect(() => {
    fetchDetails();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {}, [data]); // eslint-disable-line react-hooks/exhaustive-deps

  const [lightBoxIndex, setLightBoxIndex] = useState(-1);

  if (loadError)
    return (
      <main>
        <div className="tw-mx-auto tw-max-w-[1320px] tw-px-4 tw-py-6 tw-font-display">
          <Breadcrumb
            items={[
              { pageTitle: "Booking & Enquiry", pageUrl: "" },
              { pageTitle: "Your Trip", pageUrl: "" },
              { pageTitle: "Trip Details", pageUrl: "" },
            ]}
          />
          <div className="tw-mx-auto tw-max-w-[460px] tw-py-16 tw-text-center">
            <div className="tw-mx-auto tw-mb-5 tw-grid tw-h-20 tw-w-20 tw-place-items-center tw-rounded-full tw-bg-[#f4eefc] tw-text-[#854ec9]">
              <svg width="38" height="38" fill="currentColor" viewBox="0 0 16 16">
                <path d="M8.982 1.566a1.13 1.13 0 0 0-1.96 0L.165 13.233c-.457.778.091 1.767.98 1.767h13.713c.889 0 1.438-.99.98-1.767zM8 5c.535 0 .954.462.9.995l-.35 3.507a.552.552 0 0 1-1.1 0L7.1 5.995A.905.905 0 0 1 8 5m.002 6a1 1 0 1 1 0 2 1 1 0 0 1 0-2" />
              </svg>
            </div>
            <h2 className="tw-mb-2 tw-text-[22px] tw-font-bold tw-text-[#14101c]">
              Couldn&apos;t load this right now
            </h2>
            <p className="tw-mb-6 tw-text-[14px] tw-leading-relaxed tw-text-[#6b6577]">
              We couldn&apos;t load your trip details at the moment.
              <br />
              Please try again in a few seconds — if it keeps happening, contact
              our support team.
            </p>
            <div className="tw-flex tw-flex-wrap tw-items-center tw-justify-center tw-gap-3">
              <button
                type="button"
                onClick={() => window.location.reload()}
                className={primaryBtnCls}
              >
                Try Again
              </button>
              <a
                href={
                  "/booking/" +
                  referenceId +
                  "?token=" +
                  (data.token || searchParams.get("token") || "")
                }
                className={outlineBtnCls}
              >
                Back to Booking
              </a>
            </div>
          </div>
        </div>
      </main>
    );

  if (tourDetailsLoading)
    return (
      <main>
        <div className="tw-mx-auto tw-max-w-[1320px] tw-px-4 tw-py-6 tw-font-display">
          <Breadcrumb
            items={[
              { pageTitle: "Booking & Enquiry", pageUrl: "" },
              { pageTitle: "Your Trip", pageUrl: "" },
              { pageTitle: "Trip Details", pageUrl: "" },
            ]}
          />
          <h1 className="tw-mt-2 tw-text-[clamp(20px,2.4vw,28px)] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
            Trip Details
          </h1>
          <div className="tw-flex tw-flex-col tw-items-center tw-gap-4 tw-py-20 tw-text-[#5d556c]">
            <span className="tw-inline-block tw-h-12 tw-w-12 tw-animate-spin tw-rounded-full tw-border-4 tw-border-solid tw-border-[#854ec9] tw-border-r-transparent" />
            <p className="tw-m-0 tw-text-center tw-text-[15px]">
              Loading your order details.
              <br />
              Please wait.
            </p>
          </div>
        </div>
      </main>
    );

  return (
    <TourModalsProvider tourId={tourData.id} tourSlug={tourData.slug}>
    <main>
      <div className="tw-mx-auto tw-max-w-[1320px] tw-px-4 tw-py-6 tw-font-display">
        <Breadcrumb
          items={[
            { pageTitle: "Booking & Enquiry", pageUrl: "" },
            {
              pageTitle: data.subject,
              pageUrl: "/booking/" + referenceId + "?token=" + data.token,
            },
            { pageTitle: "Trip Details", pageUrl: "" },
          ]}
        />
        <a
          href={"/booking/" + referenceId + "?token=" + data.token}
          className="tw-inline-flex tw-items-center tw-gap-1 tw-text-[13.5px] tw-font-semibold tw-text-[#854ec9] tw-no-underline hover:tw-underline"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="18"
            height="18"
            fill="currentColor"
            viewBox="0 0 16 16"
          >
            <path
              fillRule="evenodd"
              d="M12 8a.5.5 0 0 1-.5.5H5.707l2.147 2.146a.5.5 0 0 1-.708.708l-3-3a.5.5 0 0 1 0-.708l3-3a.5.5 0 1 1 .708.708L5.707 7.5H11.5a.5.5 0 0 1 .5.5"
            />
          </svg>
          Back to Booking
        </a>

        <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-12 lg:tw-gap-6">
          <div className="lg:tw-col-span-12">
            <div className="tw-mt-2">
              <div>
                <span className="tw-text-[clamp(20px,2.4vw,28px)] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
                  {data.subject}
                </span>
              </div>
              <div className="tw-mt-1 tw-flex tw-flex-wrap tw-items-center tw-gap-x-2 tw-gap-y-1 tw-text-[13.5px] tw-text-[#6b6577]">
                <span className="tw-inline-flex">
                  <StarIcon />
                  <StarIcon />
                  <StarIcon />
                  <StarIcon />
                  <StarIcon />
                </span>
                <span>
                  {tourData.defaults?.duration?.days == 1
                    ? "Daily"
                    : tourData.defaults?.duration?.days + " Days"}
                  ,{" "}
                  {`${tourData.routes?.length} ${
                    tourData.routes?.length == 1
                      ? "Destination"
                      : "Destinations"
                  }`}
                </span>
                {tourData.startLocation && (
                  <>
                    <span className="tw-text-[#cfc9d9]">|</span>
                    <span>
                      Starts from{" "}
                      <strong className="tw-text-[#14101c]">
                        {tourData.startLocation}
                      </strong>
                    </span>
                  </>
                )}
              </div>
            </div>
          </div>

          {tourImages.length > 1 && (
            <div className="lg:tw-col-span-12">
              <Gallery
                images={tourImages}
                tourName={tourData.name}
                onLightBoxIndexChange={(index: any) => {
                  setLightBoxIndex(index);
                }}
              />
              <GalleryMobil
                images={tourImages}
                tourName={tourData.name}
                onLightBoxIndexChange={(index: any) => {
                  setLightBoxIndex(index);
                }}
              />
            </div>
          )}

          <div className="lg:tw-col-span-8">
            {tourImages.length == 1 && (
              <GallerySingle
                images={tourImages}
                tourName={tourData.name}
                onLightBoxIndexChange={(index: any) => {
                  setLightBoxIndex(index);
                }}
              />
            )}
            <Info tourData={tourData} />
            <Overview tourData={tourData} />
            <Route tourData={tourData} />
            <Places tourData={tourData} />
            <Highlights tourData={tourData} />
            <Itineraries tourData={tourData} />
            <Includes tourData={tourData} />

            <GoodToKnow />
          </div>
        </div>
      </div>
      <Lightbox
        slides={tourImages.map(({ imageUrl }: { imageUrl: any }) => ({
          src: imageUrl,
        }))}
        controller={{ closeOnBackdropClick: true }}
        index={lightBoxIndex}
        open={lightBoxIndex >= 0}
        close={() => setLightBoxIndex(-1)}
        counter={{ container: { style: { top: 0 } } }}
        plugins={[Slideshow, Thumbnails, Zoom, Counter]}
      />
    </main>
    </TourModalsProvider>
  );
}
